import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"外观与主题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/appearance.md","filePath":"zh-CN/user-guide/settings/appearance.md","lastUpdated":1787586465000}'),a={name:"zh-CN/user-guide/settings/appearance.md"};function n(i,t,l,g,d,h){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="外观与主题" tabindex="-1">外观与主题 <a class="header-anchor" href="#外观与主题" aria-label="Permalink to &quot;外观与主题&quot;">​</a></h1><p>Lertaro 提供了高颜值的现代化界面设计体系，支持精细化的主题模式切换与丰富的配色方案。外观设置页面位于设置中心左侧侧边栏底部（“关于”上方）。</p><h2 id="_1-主题模式-theme-modes" tabindex="-1">1. 主题模式（Theme Modes） <a class="header-anchor" href="#_1-主题模式-theme-modes" aria-label="Permalink to &quot;1. 主题模式（Theme Modes）&quot;">​</a></h2><p>页面顶部提供三种主题模式切换卡片，点击即可瞬间切换生效：</p><ul><li><strong>浅色模式（Light）</strong>：固定使用浅色调界面风格，下方的主题选择网格将仅展示浅色风格的主题卡片。</li><li><strong>深色模式（Dark）</strong>：固定使用深色调界面风格，下方网格将仅展示深色风格的主题卡片。</li><li><strong>跟随系统（Follow System）</strong>：界面将根据 Windows 系统的深浅色设置自动实时切换。在此模式下，下方网格会分别呈现<strong>浅色主题</strong>与<strong>深色主题</strong>两个选择区，你可以为白天和黑夜分别指定心仪的配色方案，系统切换时无需重启 Lertaro 即可平滑过渡。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro 会独立记忆你在浅色与深色模式下分别选中的主题。当你在不同模式之间切换时，已选定的配色方案绝不会丢失。</p></div><h2 id="_2-界面主题选择卡片" tabindex="-1">2. 界面主题选择卡片 <a class="header-anchor" href="#_2-界面主题选择卡片" aria-label="Permalink to &quot;2. 界面主题选择卡片&quot;">​</a></h2><p>主题选择区采用可视化的缩略图卡片网格呈现，每张卡片都真实反映了搜索框、边框阴影、文字层级与选中高亮行的实际配色效果，当前生效的主题右上角带有清晰的勾选徽标。</p><h3 id="内置与随包主题介绍" tabindex="-1">内置与随包主题介绍 <a class="header-anchor" href="#内置与随包主题介绍" aria-label="Permalink to &quot;内置与随包主题介绍&quot;">​</a></h3><ul><li><strong>核心内置主题（CoreExtensions）</strong>： <ul><li><strong>浅色（Light）</strong> / <strong>深色（Dark）</strong>：经典简约的黑白基底设计，完美融入 Windows 原生系统风格。</li><li><strong>北欧蓝（Nordic Blue）</strong>：冷色调极简极客风，低饱和度的冰蓝与深海背景。</li><li><strong>樱花粉（Sakura Pink）</strong>：柔和清新的粉白配色，细腻优雅。</li><li><strong>赛博朋克（Cyberpunk）</strong>：高对比度的霓虹黄与深紫夜色，充满未来科技感。</li></ul></li><li><strong>动漫主题包（AnimeThemes，随包提供）</strong>： <ul><li><strong>新世纪（Evangelion）</strong>、<strong>樱花盛开（Sakura Blossom）</strong>、<strong>天气之子（Weathering with You）</strong>。</li></ul></li><li><strong>臻选成对主题（Curated Themes，随包提供）</strong>： <ul><li>精心调配的 10 组浅色 / 深色成对主题：<strong>冰川蓝（Glacier Blue）</strong>、<strong>陶土棕（Terracotta）</strong>、<strong>森林绿（Forest Green）</strong>、<strong>紫水晶（Amethyst）</strong>、<strong>绯红（Crimson）</strong>、<strong>石墨灰（Graphite）</strong>、<strong>靛蓝夜（Indigo Night）</strong>、<strong>薄荷青（Mint Cyan）</strong>、<strong>香槟金（Champagne Gold）</strong>、<strong>琥珀金（Amber Gold）</strong>。</li></ul></li></ul><h3 id="插件主题扩展能力" tabindex="-1">插件主题扩展能力 <a class="header-anchor" href="#插件主题扩展能力" aria-label="Permalink to &quot;插件主题扩展能力&quot;">​</a></h3><p>所有主题均基于 <code>Lertaro.PluginSdk</code> 的 UI 主题标准规范开发。第三方开发者可以通过编写主题插件向此网格动态注册全新的个性化配色方案。</p>',12)])])}const p=r(a,[["render",n]]);export{c as __pageData,p as default};
